-- The language a person reads Backstage in, kept on the account so a link into another
-- language's team does not change it. No row means no choice: the page reads its `[lang]` segment.
--
-- Its own table, not a column on "user": that table is generated by Better Auth's CLI, and its
-- regenerate-and-diff workflow would drop a column it does not know about.
create table "user_setting" (
  "userId"    text        not null primary key references "user" ("id") on delete cascade,
  -- Not a foreign key: a removed language leaves a choice that simply reads the fallback.
  "uiLang"    text        check ("uiLang" ~ '^[a-z]{2}[A-Z]{2}$'),
  "updatedAt" timestamptz not null default now()
);
